oxy_webhelp_navlinks = {"postgresql-d39536e39851":{"topics":[{"title":"Introduction to PostgreSQL protection","href":"postgresql\/postgresql_protection_key_features.html","menu":{"hasChildren":false},"tocID":"tocId-d39536e39864","next":"tocId-d39536e39864"},{"title":"PostgreSQL protection implementation workflow","shortdesc":"<p class=\"shortdesc\">Describes the workflow for implementing PostgreSQL protection with <span class=\"ph\">RSC<\/span>, from planning through recovery.<\/p>","href":"postgresql\/postgresql_protection_workflow.html","attributes":{"data-id":"postgresql_protection_workflow"},"menu":{"hasChildren":false},"tocID":"postgresql_protection_workflow-d39536e39917","topics":[]},{"title":"Quick links for PostgreSQL","shortdesc":"<p class=\"shortdesc\">Immediate access to important tasks and information, enabling quick setup, daily         operations, and critical recovery.<\/p>","href":"postgresql\/postgresql_quick_links.html","attributes":{"data-id":"postgresql_quick_links"},"menu":{"hasChildren":false},"tocID":"postgresql_quick_links-d39536e39931","topics":[]},{"title":"Plan your PostgreSQL protection","shortdesc":"<p class=\"shortdesc\">Before setting up a PostgreSQL cluster in <span class=\"ph\">RSC<\/span>, it is necessary to         plan user and access management for designated <span class=\"ph\">RSC<\/span> users.<\/p>","href":"postgresql\/postgresql_planning_protection.html","attributes":{"data-id":"postgresql_planning_protection"},"menu":{"hasChildren":false},"tocID":"postgresql_planning_protection-d39536e39942","next":"postgresql_planning_protection-d39536e39942"},{"title":"Set up PostgreSQL clusters","shortdesc":"<p class=\"shortdesc\">You can protect PostgreSQL clusters using <span class=\"ph\">RSC<\/span> by configuring         PostgreSQL hosts         that         run them. This setup automates backups and enables rapid recovery from         ransomware threats, providing unified data security and resilience for your PostgreSQL         databases.<\/p>","href":"postgresql\/postgresql_setup.html","attributes":{"data-id":"postgresql_setup"},"menu":{"hasChildren":false},"tocID":"postgresql_setup-d39536e40028","next":"postgresql_setup-d39536e40028"},{"title":"Set up PostgreSQL protection","shortdesc":"<p class=\"shortdesc\">You can protect PostgreSQL clusters using automated, policy-driven backups, ensuring         data resilience and compliance with organizational standards.<\/p>","href":"postgresql\/postgresql_protection_setup.html","attributes":{"data-id":"postgresql_protection_setup"},"menu":{"hasChildren":false},"tocID":"postgresql_protection_setup-d39536e40139","next":"postgresql_protection_setup-d39536e40139"},{"title":"Manage PostgreSQL protection","shortdesc":"<p class=\"shortdesc\">After you set up PostgreSQL protection in <span class=\"ph\">RSC<\/span>, you can configure SLA         Domains, assign protection to PostgreSQL clusters, and manage the lifecycle of PostgreSQL         snapshots.<\/p>","href":"postgresql\/postgresql_manage_protection.html","attributes":{"data-id":"postgresql_manage_protection"},"menu":{"hasChildren":false},"tocID":"postgresql_manage_protection-d39536e40255","next":"postgresql_manage_protection-d39536e40255"},{"title":"Recover PostgreSQL","shortdesc":"<p class=\"shortdesc\">After <span class=\"ph\">RSC<\/span> takes snapshots of your PostgreSQL workloads, you can         recover the required workloads using different recovery options.<\/p>","href":"postgresql\/postgresql_recovery.html","attributes":{"data-id":"postgresql_recovery"},"menu":{"hasChildren":false},"tocID":"postgresql_recovery-d39536e40434","next":"postgresql_recovery-d39536e40434"},{"title":"Configure High Availability for a PostgreSQL cluster","shortdesc":"<p class=\"shortdesc\">High Availability for PostgreSQL clusters protects a primary and standby cluster         setup and maintains backup continuity when a failover promotes a standby cluster to the         primary role.<\/p>","href":"postgresql\/ha_postgres_cluster.html","attributes":{"data-id":"ha_postgres_cluster"},"menu":{"hasChildren":false},"tocID":"ha_postgres_cluster-d39536e40555","next":"ha_postgres_cluster-d39536e40555"}]}};